fn expr(cs: List[String], i: Int) -> Result[(Int, Int, Bool), String] {
  let f = try term(cs, i)
  var v = f.0
  var j = f.1
  var z = f.2
  while at(cs, j) == "+" || at(cs, j) == "-" || at(cs, j) == "%" {
    let op = at(cs, j)
    let g = try term(cs, j + 1)
    if op == "+" {
      v = v + g.0
    } else if op == "-" {
      v = v - g.0
    } else if g.0 == 0 {
      z = true
      v = 0
    } else {
      v = v - g.0 * (v / g.0)
    }
    z = z || g.2
    j = g.1
  }
  return Ok((v, j, z))
}

