}

fn valid_version(v: String) -> Bool {
  let parts = split(v, ".")
  if len(parts) > 4 {
    return false
  }
  for p in parts {
    let cs = split(p, "")
    if len(cs) == 0 || !all_digits(cs) {
      return false
    }
  }
  return true
}

