    |> drop(i)
    |> first()
    |> unwrap_or(0)
}

fn sign(d: Int) -> Int {
  if d < 0 {
    return -1
  }
  return 1
}

fn compare_versions(a: String, b: String) -> Result[Int, String] {
  let a_clean = if starts_with(a, "v") || starts_with(a, "V") { drop(a, 1) } else { a }
  let b_clean = if starts_with(b, "v") || starts_with(b, "V") { drop(b, 1) } else { b }
  if !valid_version(a_clean) {
    return Err("bad version: " + a)
  }
  if !valid_version(b_clean) {
    return Err("bad version: " + b)
  }
  let x = map(split(a_clean, "."), |p| unwrap_or(parse_int(p), 0))
  let y = map(split(b_clean, "."), |p| unwrap_or(parse_int(p), 0))
  let diffs = filter(map(range(0, 4), |i| part_at(x, i) - part_at(y, i)), |d| d != 0)
  return match first(diffs) {
    Some(d) => Ok(sign(d)),
    None => Ok(0),
  }
}

