type EditOp =
  | Insert(text: String)
  | Delete(n: Int)
  | Left(n: Int)
  | Right(n: Int)
  | Undo
  | Redo

type Editor {
  text: String,
  cur: Int,
  history: List[(String, Int)],
  redo_history: List[(String, Int)],
}

fn step(e: Editor, op: EditOp) -> Editor {
  let cs = split(e.text, "")
  let saved = append(e.history, (e.text, e.cur))
  let redo_saved = append(e.redo_history, (e.text, e.cur))
  return match op {
    Insert(t) => insert(e, t, saved, redo_saved),
    Delete(n) => delete(e, min(n, e.cur), saved, redo_saved),
    Left(n) => Editor { text: e.text, cur: max(0, e.cur - n), history: e.history, redo_history: e.redo_history },
    Right(n) => Editor { text: e.text, cur: min(len(cs), e.cur + n), history: e.history, redo_history: e.redo_history },
    Undo => undo(e),
    Redo => redo(e),
  }
