from collections import deque

MAX_FAILURES = 3


def door_lock(code: str, events: list[Key]) -> str:
    """Simulate a keypad lock and return its final state."""
    state = "locked"
    buffer: deque[str] = deque(maxlen=len(code))
    failures = 0
    for event in events:
        if state == "blocked":
            if event["kind"] == "Reset":
                state = "locked"
                buffer.clear()
                failures = 0
            break
        if state == "open":
            if event["kind"] == "Enter":
                state = "locked"
                buffer.clear()
            continue
        if event["kind"] == "Digit":
            buffer.append(str(event["d"]))
        elif event["kind"] == "Clear":
            buffer.clear()
        elif event["kind"] == "Reset":
            continue
        else:
            if "".join(buffer) == code:
                state = "open"
                failures = 0
            else:
                failures += 1
                if failures >= MAX_FAILURES:
                    state = "blocked"
            buffer.clear()
    return state

