def elevator_scan(start: int, requests: list[int], direction: str) -> list[int]:
    """Return the order in which an elevator serves requested floors (SCAN)."""
    floors = set(requests)
    here = [start] if start in floors else []
    above = sorted(f for f in floors if f > start)
    below = sorted((f for f in floors if f < start), reverse=True)

    if direction == "nearest":
        closest_above = next((f for f in above if f >= start), None)
        closest_below = next((f for f in below if f <= start), None)
        if closest_above is not None and closest_below is not None:
            if closest_above - start < start - closest_below:
                direction = "up"
            else:
                direction = "down"
        elif closest_above is not None:
            direction = "up"
        elif closest_below is not None:
            direction = "down"
        else:
            direction = "up"

    if direction == "up":
        return here + above + below
    return here + below + above

