_TRANSITIONS: dict[str, dict[str, str]] = {
    "pay": {"created": "paid"},
    "ship": {"paid": "shipped"},
    "cancel": {"created": "cancelled", "paid": "cancelled"},
    "refund": {"paid": "refunded", "shipped": "refunded"},
}

