export function elevator_scan(start: number, requests: number[], direction: string): number[] {
  const floors = [...new Set(requests)].sort((a, b) => a - b);
  const above = floors.filter((f) => f > start);
  const below = floors.filter((f) => f < start);
  const here = floors.includes(start) ? [start] : [];
  const closestAbove = above.length > 0 ? above[0] : Infinity;
  const closestBelow = below.length > 0 ? below[below.length - 1] : -Infinity;
  const closest = Math.abs(closestAbove - start) < Math.abs(closestBelow - start) ? "up" : "down";
  return closest === "up" ? [...here, ...above, ...below] : [...here, ...below, ...above];
}

