export function k_most_frequent(xs: number[], k: number): [number, number][] {
  if (k <= 0) return [];
  const counts = new Map<number, { count: number; index: number }>();
  for (const [i, x] of xs.entries()) {
    counts.set(x, { count: (counts.get(x)?.count ?? 0) + 1, index: i });
  }
  const pairs: [number, number][] = [...counts.entries()].map(([x, { count, index }]) => [x, count, index]);
  pairs.sort((p, q) => {
    if (p[1] === q[1]) return p[2] - q[2];
    return q[1] - p[1];
  });
  return pairs.slice(0, k).map(([x, count]) => [x, count]);
}

