  const regions = [...byRegion.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
  return regions.flatMap((r) => {
    const m = byRegion.get(r)!;
    let maxRevenue = 0;
    for (const [_, v] of m) {
      if (v > maxRevenue) maxRevenue = v;
    }
    const bestProducts = [...m.entries()].filter(([_, v]) => v === maxRevenue).map(([p, _]) => p);
    bestProducts.sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
    return bestProducts.map((p) => [r, p, maxRevenue] as [string, string, number]);
  });
}
